# Structured start: every target pair G-C, unpaired A
stack=[]
tpairs={}
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        tpairs[(j,i)]=1
base = ['A']*len(target)
for (i,j) in tpairs:
    base[i]='G'; base[j]='C'
base = ''.join(base)

def worker(seed):
    random.seed(seed)
    for _ in range(80):
        # perturb base: flip ~10% of positions
        start = list(base)
        for k in range(len(start)):
            if random.random() < 0.10:
                start[k] = random.choice('ACGU')
        start = ''.join(start)
        seq, d = RNA.inverse_fold(start, target)
        if d == 0:
            st = RNA.fold_compound(seq).mfe()[0]
            if st == target:
                return seq
    return None

if __name__ == '__main__':
    t0=time.time()
    with mp.Pool(48) as p:
        for r in p.imap_unordered(worker, range(960)):
            if r:
                print('SOLVED', r, 'time', int(time.time()-t0))
                p.terminate(); break
        else:
            print('NONE', 'time', int(time.time()-t0))
